using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;

namespace Framework.Parameters
{
    /// <summary>
    /// 単一パラメーターの実行時の値と補正情報を管理する。
    /// </summary>
    /// <typeparam name="TParameter">
    /// パラメーターを識別する型。
    /// </typeparam>
    /// <remarks>
    /// 定義情報は共有可能だが、実行時の状態は個体ごとに保持する。
    /// 最終値は状態変更時に再計算し、参照時には再計算しない。
    /// メインスレッドからの利用を想定する。
    /// </remarks>
    public sealed class RuntimeParameter<TParameter>
    {
        /// <summary>
        /// 登録されている補正情報の一覧。
        /// </summary>
        private readonly List<ParameterModifier> modifiers =
            new List<ParameterModifier>();

        /// <summary>
        /// 外部公開用の読み取り専用補正一覧。
        /// </summary>
        private readonly ReadOnlyCollection<ParameterModifier>
            readOnlyModifiers;

        /// <summary>
        /// 現在の補正前の基本値。
        /// </summary>
        private float baseValue;

        /// <summary>
        /// 補正適用後のキャッシュされた最終値。
        /// </summary>
        private float currentValue;

        /// <summary>
        /// 変更通知を実行しているかどうか。
        /// </summary>
        private bool isNotifying;

        /// <summary>
        /// パラメーターの共通定義を取得する。
        /// </summary>
        public ParameterDefinition<TParameter> Definition { get; }

        /// <summary>
        /// パラメーターの識別子を取得する。
        /// </summary>
        public TParameter Id => Definition.Id;

        /// <summary>
        /// 個体生成時に指定された初期値を取得する。
        /// </summary>
        public float InitialValue { get; }

        /// <summary>
        /// 現在の補正前の基本値を取得する。
        /// </summary>
        public float BaseValue => baseValue;

        /// <summary>
        /// すべての補正を適用した最終値を取得する。
        /// </summary>
        public float Value => currentValue;

        /// <summary>
        /// 最終値を0から1に正規化した値を取得する。
        /// </summary>
        public float NormalizedValue =>
            Definition.Normalize(currentValue);

        /// <summary>
        /// 登録されている補正の件数を取得する。
        /// </summary>
        public int ModifierCount => modifiers.Count;

        /// <summary>
        /// 補正が登録されているかどうかを取得する。
        /// </summary>
        public bool HasModifiers => modifiers.Count > 0;

        /// <summary>
        /// 登録されている補正の読み取り専用一覧を取得する。
        /// </summary>
        public IReadOnlyList<ParameterModifier> Modifiers =>
            readOnlyModifiers;

        /// <summary>
        /// 最終値が変化した際に発生するイベント。
        /// 引数は変更前の値、変更後の値の順となる。
        /// </summary>
        /// <remarks>
        /// 状態更新後に通知する。
        /// 通知中の同一パラメーターへの変更は禁止する。
        /// </remarks>
        public event Action<float, float> ValueChanged;

        /// <summary>
        /// 定義の標準初期値を使用して生成する。
        /// </summary>
        /// <param name="definition">パラメーターの定義</param>
        /// <exception cref="ArgumentNullException">
        /// 定義がnullの場合に発生する。
        /// </exception>
        public RuntimeParameter(
            ParameterDefinition<TParameter> definition)
            : this(
                definition,
                definition != null
                    ? definition.DefaultValue
                    : 0f)
        {
        }

        /// <summary>
        /// 個体固有の初期値を指定して生成する。
        /// </summary>
        /// <param name="definition">パラメーターの定義</param>
        /// <param name="initialValue">個体固有の初期値</param>
        /// <exception cref="ArgumentNullException">
        /// 定義がnullの場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 初期値が有限値ではない場合、
        /// または定義の有効範囲外の場合に発生する。
        /// </exception>
        public RuntimeParameter(
            ParameterDefinition<TParameter> definition,
            float initialValue)
        {
            if (definition == null)
            {
                throw new ArgumentNullException(
                    nameof(definition));
            }

            if (!definition.IsInRange(initialValue))
            {
                throw new ArgumentOutOfRangeException(
                    nameof(initialValue),
                    "初期値が有効範囲外です。");
            }

            Definition = definition;
            InitialValue = initialValue;

            baseValue = initialValue;
            currentValue = initialValue;

            // 読み取り専用一覧は生成時に一度だけ作成する。
            readOnlyModifiers = modifiers.AsReadOnly();
        }

        /// <summary>
        /// 補正前の基本値を変更する。
        /// </summary>
        /// <param name="value">新しい基本値</param>
        /// <returns>基本値が変化した場合はtrue</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 指定値が有限値ではない場合に発生する。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public bool SetBaseValue(float value)
        {
            EnsureCanModify();

            float clampedValue = Definition.Clamp(value);

            // 基本値が変化しない場合は再計算しない。
            if (baseValue == clampedValue)
            {
                return false;
            }

            baseValue = clampedValue;

            RecalculateValue();

            return true;
        }

        /// <summary>
        /// 現在の基本値に指定された数値を加算する。
        /// </summary>
        /// <param name="amount">
        /// 加算量。負数の場合は減算となる。
        /// </param>
        /// <returns>基本値が変化した場合はtrue</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 加算量が有限値ではない場合に発生する。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public bool AddBaseValue(float amount)
        {
            EnsureCanModify();

            if (float.IsNaN(amount) ||
                float.IsInfinity(amount))
            {
                throw new ArgumentOutOfRangeException(
                    nameof(amount));
            }

            // 中間計算をdoubleで行い、floatの範囲超過を防ぐ。
            double result = (double)baseValue + amount;

            return SetBaseValue(ClampCalculatedValue(result));
        }

        /// <summary>
        /// 補正情報を追加する。
        /// </summary>
        /// <param name="modifier">追加する補正情報</param>
        /// <returns>
        /// 追加に成功した場合はtrue。
        /// 同一IDの補正が登録済みの場合はfalse。
        /// </returns>
        /// <exception cref="ArgumentNullException">
        /// 補正情報がnullの場合に発生する。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public bool TryAddModifier(ParameterModifier modifier)
        {
            EnsureCanModify();

            if (modifier == null)
            {
                throw new ArgumentNullException(
                    nameof(modifier));
            }

            if (HasModifier(modifier.Id))
            {
                return false;
            }

            modifiers.Add(modifier);

            RecalculateValue();

            return true;
        }

        /// <summary>
        /// 指定されたIDの補正が登録されているか判定する。
        /// </summary>
        /// <param name="id">検索対象の補正ID</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool HasModifier(Guid id)
        {
            for (int i = 0; i < modifiers.Count; i++)
            {
                if (modifiers[i].MatchesId(id))
                {
                    return true;
                }
            }

            return false;
        }

        /// <summary>
        /// 指定されたIDの補正情報を取得する。
        /// </summary>
        /// <param name="id">検索対象の補正ID</param>
        /// <param name="modifier">
        /// 取得した補正情報。失敗時はnull。
        /// </param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetModifier(
            Guid id,
            out ParameterModifier modifier)
        {
            for (int i = 0; i < modifiers.Count; i++)
            {
                if (modifiers[i].MatchesId(id))
                {
                    modifier = modifiers[i];

                    return true;
                }
            }

            modifier = null;

            return false;
        }

        /// <summary>
        /// 指定されたIDの補正を解除する。
        /// </summary>
        /// <param name="id">解除対象の補正ID</param>
        /// <returns>解除に成功した場合はtrue</returns>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public bool TryRemoveModifier(Guid id)
        {
            EnsureCanModify();

            for (int i = 0; i < modifiers.Count; i++)
            {
                if (!modifiers[i].MatchesId(id))
                {
                    continue;
                }

                modifiers.RemoveAt(i);

                RecalculateValue();

                return true;
            }

            return false;
        }

        /// <summary>
        /// 指定された補正元による補正をすべて解除する。
        /// </summary>
        /// <param name="source">解除対象の補正元</param>
        /// <returns>
        /// 解除した補正の件数。
        /// 補正元がnullの場合は0。
        /// </returns>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public int RemoveModifiersBySource(object source)
        {
            EnsureCanModify();

            if (source == null)
            {
                return 0;
            }

            int removedCount = 0;

            // 削除によるインデックスの変化を避けるため逆順に走査する。
            for (int i = modifiers.Count - 1; i >= 0; i--)
            {
                if (!modifiers[i].IsFromSource(source))
                {
                    continue;
                }

                modifiers.RemoveAt(i);

                removedCount++;
            }

            // 一括解除後に一度だけ再計算する。
            if (removedCount > 0)
            {
                RecalculateValue();
            }

            return removedCount;
        }

        /// <summary>
        /// 登録されているすべての補正を解除する。
        /// </summary>
        /// <returns>解除した補正の件数</returns>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public int ClearModifiers()
        {
            EnsureCanModify();

            int removedCount = modifiers.Count;

            if (removedCount == 0)
            {
                return 0;
            }

            modifiers.Clear();

            RecalculateValue();

            return removedCount;
        }

        /// <summary>
        /// 基本値のみを個体生成時の初期値に戻す。
        /// </summary>
        /// <returns>基本値が変化した場合はtrue</returns>
        /// <remarks>
        /// 登録済みの補正は維持する。
        /// </remarks>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public bool ResetBaseValue()
        {
            return SetBaseValue(InitialValue);
        }

        /// <summary>
        /// 基本値と補正情報を個体生成時の状態に戻す。
        /// </summary>
        /// <remarks>
        /// 基本値を初期値に戻し、すべての補正を解除する。
        /// 変更通知は最大で一度だけ発生する。
        /// </remarks>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中に呼び出された場合に発生する。
        /// </exception>
        public void Reset()
        {
            EnsureCanModify();

            baseValue = InitialValue;

            modifiers.Clear();

            RecalculateValue();
        }

        /// <summary>
        /// 基本値と補正情報から最終値を再計算する。
        /// </summary>
        private void RecalculateValue()
        {
            // 加算補正の合計値。
            double additiveTotal = 0d;

            // 乗算補正の累積倍率。
            double multiplierTotal = 1d;

            // ゼロ倍率の補正が存在するかどうか。
            bool hasZeroMultiplier = false;

            for (int i = 0; i < modifiers.Count; i++)
            {
                ParameterModifier modifier = modifiers[i];

                switch (modifier.Type)
                {
                    case ParameterModifierType.Additive:

                        additiveTotal += modifier.Value;

                        break;

                    case ParameterModifierType.Multiplicative:

                        if (modifier.Value == 0f)
                        {
                            hasZeroMultiplier = true;
                        }
                        else
                        {
                            multiplierTotal *= modifier.Value;
                        }

                        break;
                }
            }

            // 加算補正後の値を計算する。
            double additiveValue =
                (double)baseValue + additiveTotal;

            double result;

            // 無限大とゼロの乗算によるNaNを回避する。
            if (hasZeroMultiplier || additiveValue == 0d)
            {
                result = 0d;
            }
            else
            {
                result = additiveValue * multiplierTotal;
            }

            float newValue = ClampCalculatedValue(result);

            // 最終値が変化していない場合は通知しない。
            if (currentValue == newValue)
            {
                return;
            }

            float previousValue = currentValue;

            // 状態を更新してからイベントを通知する。
            currentValue = newValue;

            NotifyValueChanged(previousValue, currentValue);
        }

        /// <summary>
        /// 計算結果を定義の有効範囲内に制限する。
        /// </summary>
        /// <param name="value">制限対象の計算結果</param>
        /// <returns>有効範囲内に制限された値</returns>
        private float ClampCalculatedValue(double value)
        {
            if (value <= Definition.MinValue)
            {
                return Definition.MinValue;
            }

            if (value >= Definition.MaxValue)
            {
                return Definition.MaxValue;
            }

            return (float)value;
        }

        /// <summary>
        /// 最終値の変更を購読者へ通知する。
        /// </summary>
        /// <param name="previousValue">変更前の最終値</param>
        /// <param name="newValue">変更後の最終値</param>
        private void NotifyValueChanged(
            float previousValue,
            float newValue)
        {
            isNotifying = true;

            try
            {
                ValueChanged?.Invoke(
                    previousValue,
                    newValue);
            }
            finally
            {
                // 購読側で例外が発生した場合も通知状態を解除する。
                isNotifying = false;
            }
        }

        /// <summary>
        /// 現在の状態でパラメーターを変更可能か検証する。
        /// </summary>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中の場合に発生する。
        /// </exception>
        private void EnsureCanModify()
        {
            if (isNotifying)
            {
                throw new InvalidOperationException(
                    "変更通知中は同一パラメーターを変更できません。");
            }
        }
    }
}
